:root { font-family: system-ui, sans-serif; color: #1b2838; background: #f5f7fa; }
* { box-sizing: border-box; }
body { margin: 0; }
main { max-width: 780px; margin: 64px auto; padding: 0 24px; }
h1 { font-size: 2.25rem; letter-spacing: -.04em; overflow-wrap: anywhere; }
form { display: grid; grid-template-columns: 1fr auto; gap: 10px 14px; padding: 24px; background: white; border: 1px solid #dce2e9; border-radius: 12px; }
label { grid-column: 1 / -1; font-weight: 600; }
input, button { font: inherit; border-radius: 6px; padding: 10px 14px; }
input { min-width: 0; border: 1px solid #8c98a8; }
button { cursor: pointer; color: white; background: #2157b0; border: 1px solid #2157b0; font-weight: 600; }
button.secondary { background: white; color: #2157b0; border-color: #c6d3e5; }
button:disabled { opacity: .6; cursor: wait; }
:focus-visible { outline: 3px solid #609ef3; outline-offset: 3px; }
.project-list { display: grid; gap: 12px; margin-top: 28px; }
.project-row { display: flex; align-items: center; justify-content: space-between; gap: 20px; padding: 20px 24px; background: white; border: 1px solid #dce2e9; border-radius: 10px; }
.project-row span { overflow-wrap: anywhere; min-width: 0; font-weight: 600; }
.project-row button { flex-shrink: 0; }
.error { color: #9d2020; padding: 12px; background: #fff0f0; border-radius: 6px; }
@media (max-width: 480px) { main { margin-top: 32px; padding: 0 16px; } form { grid-template-columns: 1fr; } .project-row { padding: 16px; gap: 12px; } }

